window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8cc28a0526026be2"]={"versions": [{"id": "FIG-8cc28a0526026be2", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Pwm_SetDutyCycle()</code>) im Kontext des AUTOSAR Microcontroller Abstraction Layer (MCAL). Das Diagramm spezifiziert den synchronen Aufruf zur Einstellung des Tastverhältnisses an einem PWM-Kanal durch einen Treiber-Nutzer (z. B. komplexer Treiber, I/O-Hardware-Abstraktion oder SWC).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Pwm User</code>: Aufrufende Entität / Software-Komponente oberhalb des MCAL.\n</li><li><code>PWM Driver</code>: MCAL-Treibermodul für Pulsweitenmodulation.\n</li><li>Schnittstelle: Synchroner Funktionsaufruf <code>Pwm_SetDutyCycle(ChannelNumber, DutyCycle)</code>.\n</li><li>Rückkehr: Synchrone Kontrollrückgabe (<code>return</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>Pwm User</code> initiiert den synchronen Aufruf <code>Pwm_SetDutyCycle(ChannelNumber, DutyCycle)</code> an den <code>PWM Driver</code>.\n</li><li>Während der Bearbeitung im <code>PWM Driver</code> ist die Aktivierungsleiste aktiv.\n</li><li>Nach Ausführung der Funktion erfolgt die Kontrollrückgabe (<code>return</code>) an den <code>Pwm User</code>.\n</li><li>Der Wechsel des Tastverhältnisses erfolgt laut Textnotiz entweder am Ende der laufenden Periode (sofern von der Implementierung/Hardware unterstützt) oder unmittelbar direkt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Sequenz dokumentiert die Signatur und das synchrone Ausführungsverhalten der Treiberfunktion <code>Pwm_SetDutyCycle</code>. Wesentlich für Implementierer und Integratoren ist die Randbedingung bezüglich des Aktualisierungszeitpunkts des Duty-Cycle-Registers: Abhängig von der Hardwareunterstützung greift die Änderung erst mit Periodenende oder sofort; die Funktion selbst kehrt synchron nach Konfiguration zurück.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b397fdaf3d334d15", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Pwm_SetDutyCycle()</code>) im formalen AUTOSAR-Metamodell-Kontext (MCAL). Es modelliert die Interaktion zwischen der generischen Anwenderebene und dem PWM-Treibermodul (<code>«module»</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Generic Elements::Pwm User</code>: Repräsentiert die generische Benutzerinstanz oberhalb der Treiberabstraktion.\n</li><li><code>«module» Pwm::Pwm</code>: Formal als AUTOSAR-Modul typisierte Zielkomponente im Namensraum <code>Pwm</code>.\n</li><li>Aufrufschnittstelle: <code>Pwm_SetDutyCycle(ChannelNumber,DutyCycle)</code>.\n</li><li>Rückkehrnachricht: Typisierte synchrone Rückmeldung <code>Pwm_SetDutyCycle</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>Generic Elements::Pwm User</code> ruft synchron <code>Pwm_SetDutyCycle(ChannelNumber,DutyCycle)</code> auf dem Modul <code>Pwm::Pwm</code> auf.\n</li><li>Der Ausführungsbalken auf der Lebenslinie von <code>Pwm::Pwm</code> dokumentiert die Bearbeitung im Treiber.\n</li><li>Nach Abarbeitung kehrt der Kontrollfluss mit der Rückgabenachricht <code>Pwm_SetDutyCycle</code> zum Aufrufer zurück.\n</li><li>Gemäß integrierter Spezifikationsnotiz erfolgt die Umschaltung des PWM-Tastverhältnisses hardwareabhängig entweder am Ende der aktuellen Periode oder unmittelbar.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikationsnote dokumentiert den Status (<code>proposed by DB as per SWS Pwm Driver 1.0.9</code>) sowie die funktionale Verhaltensanforderung. Treiber-Implementierungen müssen berücksichtigen, ob die Ziel-Hardware gepufferte/periodensynchrone Register-Updates unterstützt; die Schnittstelle selbst blockiert nicht über Periodengrenzen hinweg, sondern liefert den Funktionsrücksprung direkt nach Konfiguration ab.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b34f279e895d55f9", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Pwm_SetDutyCycle()</code>) im formalen AUTOSAR-Metamodell-Kontext (MCAL). Es modelliert die Interaktion zwischen der generischen Anwenderebene und dem PWM-Treibermodul (<code>«module»</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Generic Elements::Pwm User</code>: Repräsentiert die generische Benutzerinstanz oberhalb der Treiberabstraktion.\n</li><li><code>«module» Pwm::Pwm</code>: Formal als AUTOSAR-Modul typisierte Zielkomponente im Namensraum <code>Pwm</code>.\n</li><li>Aufrufschnittstelle: <code>Pwm_SetDutyCycle(ChannelNumber,DutyCycle)</code>.\n</li><li>Rückkehrnachricht: Typisierte synchrone Rückmeldung <code>Pwm_SetDutyCycle</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>Generic Elements::Pwm User</code> ruft synchron <code>Pwm_SetDutyCycle(ChannelNumber,DutyCycle)</code> auf dem Modul <code>Pwm::Pwm</code> auf.\n</li><li>Der Ausführungsbalken auf der Lebenslinie von <code>Pwm::Pwm</code> dokumentiert die Bearbeitung im Treiber.\n</li><li>Nach Abarbeitung kehrt der Kontrollfluss mit der Rückgabenachricht <code>Pwm_SetDutyCycle</code> zum Aufrufer zurück.\n</li><li>Gemäß integrierter Spezifikationsnotiz erfolgt die Umschaltung des PWM-Tastverhältnisses hardwareabhängig entweder am Ende der aktuellen Periode oder unmittelbar.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikationsnote dokumentiert den Status (<code>proposed by DB as per SWS Pwm Driver 1.0.9</code>) sowie die funktionale Verhaltensanforderung. Treiber-Implementierungen müssen berücksichtigen, ob die Ziel-Hardware gepufferte/periodensynchrone Register-Updates unterstützt; die Schnittstelle selbst blockiert nicht über Periodengrenzen hinweg, sondern liefert den Funktionsrücksprung direkt nach Konfiguration ab.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-8cc28a0526026be2", "to": "FIG-b397fdaf3d334d15", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>UML-Strukturierung &amp; Modellierung</strong>: Ergänzung des Stereotyps <code>«module»</code> und Paketpfads <code>Pwm::Pwm</code> für den PWM-Treiber sowie <code>Generic Elements::Pwm User</code> für den Benutzer.\n</li><li><strong>Rückgabenachricht</strong>: Änderung der Beschriftung des gestrichelten Rückwärtspfeils von generischem <code>return</code> zu <code>Pwm_SetDutyCycle</code>.\n</li><li><strong>Kommentarnote</strong>: Verlagerung der Funktionsbeschreibung aus dem Diagrammrand in eine strukturierte Metadaten-Note am unteren Rand mit Feldern für <code>Status</code>, <code>Description</code> und <code>Comments:</code>.\n</li></ul>"}, {"from": "FIG-b397fdaf3d334d15", "to": "FIG-b34f279e895d55f9", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
